-- Batch 8/12: Cardiac Emergencies MCQs 176-200
-- Focus: Cardiac Imaging, Point-of-Care Ultrasound, ECG Interpretation
-- Sources: Tintinalli 9e Ch 58-60, Roberts & Hedges 7e, Step-Up to EM

DO $$
DECLARE
    tid UUID;
BEGIN
    SELECT id INTO tid FROM topics WHERE slug = 'em-cardiac-emergencies' LIMIT 1;
    IF tid IS NULL THEN RAISE EXCEPTION 'Topic not found'; END IF;


END $$;
